import dev.hua.ptcglive.ai.*;
import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class NonPokemonBatch107Test {
    static final List<String> IDS=List.of("xy5_en_140");
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static UUID active(ServerMatch m,UUID p){return m.activePokemonView(p).pokemonId();}
    static UUID bench(ServerMatch m,UUID p){return m.benchPokemonView(p).getFirst().pokemonId();}
    static CardInstance hand(ServerMatch m,UUID p,String id){return DynamicPassiveModifierTest.hand(m,p,id);}
    static TrainerProfile profile(){return NonPokemonBatch2Test.DATA.trainer(IDS.getFirst()).orElseThrow();}
    static boolean has(ServerMatch m,UUID p,UUID host){return NonPokemonBatch105Test.has(m,p,host);}
    static ServerMatch game(){return DynamicPassiveModifierTest.fixture(DynamicPassiveModifierTest.plainTool(),profile(),EnergyProfile.fixed(EnergyType.COLORLESS,2),GeneratedRuleBatch8Test.hit(40,false),List.of(NonPokemonBatch105Test.draw(),NonPokemonBatch105Test.retreat()),0,DynamicPassiveModifierTest.plainStadium());}
    static ServerMatch aiGame(String id){var c=new GeneratedRuleBatch28Test.Config();c.trainer=profile();c.ownAbility=NonPokemonBatch105Test.draw();c.attack=GeneratedRuleBatch8Test.hit(200,false);c.defenderAttack=c.attack;return GeneratedRuleBatch28Test.fixture(c);}
    public static void main(String[] args){fields();moonPriority();offField();handPlayLock();prizes();ai();schema();System.out.println("NonPokemonBatch107Test passed: Silent Lab both Basic fields/hand/discard, evolution/devolution/new entries, replacement/removal, New Moon before/after Lab and dependency loss/re-entry, Ho-Oh discard suppression, actual Prize Lucky Bonus, four AI difficulties and strict Stadium contract");}
    static void fields(){for(boolean replace:List.of(false,true))for(UUID actor:List.of(DynamicPassiveModifierTest.A,DynamicPassiveModifierTest.B)){
        var m=game();UUID a=DynamicPassiveModifierTest.A,b=DynamicPassiveModifierTest.B;if(actor.equals(b))m.endTurn(a);m.playTrainer(actor,hand(m,actor,"stadium").instanceId(),null);
        for(UUID p:List.of(a,b)){check(!has(m,p,active(m,p))&&!has(m,p,bench(m,p)),"Lab failed both fields");check(m.activeRetreatCost(p)==3,"Lab retained Basic passive modifier");}
        UUID evolved=bench(m,actor);m.evolveByEffect(actor,evolved,hand(m,actor,"evolved").instanceId(),EvolutionPermission.CARD_EFFECT_ALL_TIMING);check(has(m,actor,evolved),"Lab suppressed evolved Pokemon");m.switchActiveByEffect(actor,actor,evolved);check(has(m,actor,evolved)&&m.activeRetreatCost(actor)==2,"Lab stage filter depended on position");m.devolvePokemonToHandByEffect(actor,actor,evolved);check(!has(m,actor,evolved),"Lab missed devolution");
        var entering=hand(m,actor,"basic");m.playBasicPokemonToBench(actor,entering.instanceId());check(!has(m,actor,PokemonIdentityTestSupport.logical(m,actor,entering.instanceId())),"Later Basic escaped Lab");if(replace){m.endTurn(actor);UUID other=actor.equals(a)?b:a;m.playTrainer(other,hand(m,other,"item").instanceId(),null);}else m.discardStadiumByEffect(actor);for(UUID p:List.of(a,b))check(has(m,p,active(m,p)),"Discarding Lab retained suppression");
    }}
    static ServerMatch moons(){var c=new GeneratedRuleBatch28Test.Config();c.trainer=profile();c.ownAbility=NonPokemonBatch2Test.DATA.pokemon("sv3_en_092").orElseThrow().ability("new-moon").orElseThrow();c.names=Map.of("attacker","Lunatone","source","Solrock");return GeneratedRuleBatch28Test.fixture(c);}
    static UUID add(ServerMatch m,UUID p,String id){var card=hand(m,p,id);m.playBasicPokemonToBench(p,card.instanceId());return PokemonIdentityTestSupport.logical(m,p,card.instanceId());}
    static void moonPriority(){UUID a=GeneratedRuleBatch8Test.A,b=GeneratedRuleBatch8Test.B;
        var m=moons();UUID rock=add(m,a,"source");m.playTrainer(a,hand(m,a,"trainer").instanceId(),null);check(has(m,a,active(m,a)),"Working New Moon should precede newly played Lab");
        UUID laterMoon=add(m,a,"attacker");check(has(m,a,laterMoon),"Existing New Moon failed to protect new entrant");
        m.movePokemonByEffect(a,a,rock,LeavePlayDestination.DISCARD);check(!has(m,a,active(m,a))&&!has(m,a,laterMoon),"New Moon persisted without Solrock");
        add(m,a,"source");check(!has(m,a,active(m,a))&&!has(m,a,laterMoon),"Returning Solrock resurrected New Moon already erased by Lab");
        m.discardStadiumByEffect(a);check(has(m,a,active(m,a)),"Lab departure failed to restore New Moon");m.endTurn(a);m.endTurn(b);m.playTrainer(a,hand(m,a,"trainer").instanceId(),null);check(has(m,a,active(m,a)),"New Lab retained an old suppression priority");
        var late=moons();late.playTrainer(a,hand(late,a,"trainer").instanceId(),null);add(late,a,"source");UUID incoming=add(late,a,"attacker");check(!has(late,a,active(late,a))&&!has(late,a,incoming),"Lab-first allowed later New Moon activation");
        var evolved=moons();add(evolved,a,"source");evolved.playTrainer(a,hand(evolved,a,"trainer").instanceId(),null);UUID host=active(evolved,a);evolved.evolveByEffect(a,host,hand(evolved,a,"evolved").instanceId(),EvolutionPermission.CARD_EFFECT_ALL_TIMING);evolved.devolvePokemonToHandByEffect(a,a,host);check(has(evolved,a,host),"Other surviving New Moon failed to protect returned Basic");
    }
    static void offField(){var m=NonPokemonBatch106Test.zones(profile());UUID a=DynamicPassiveModifierTest.A,b=DynamicPassiveModifierTest.B;var ho=hand(m,b,"reviver");m.discardHandCardsByEffect(a,b,List.of(ho.instanceId()));m.playTrainer(a,hand(m,a,"trainer").instanceId(),null);m.endTurn(a);if(m.hasPendingEmergencyEntry())m.decideEmergencyEntry(b,false);check(!m.canUseDiscardAbility(b,ho.instanceId(),"reviving-flame"),"Basic discard Ability remained usable");check(!m.matchesEffectCondition(b,active(m,b),new ConditionDefinition(ConditionType.DISCARD_COUNT,Map.of("ability_id","reviving-flame","value","1","comparison",">="),List.of())),"Basic discard count retained removed Ability");m.discardStadiumByEffect(b);check(m.canUseDiscardAbility(b,ho.instanceId(),"reviving-flame"),"Discard Ability failed live restoration");}
    static void prizes(){for(boolean accept:List.of(false,true)){
        var c=new GeneratedRuleBatch28Test.Config();c.trainer=profile();c.ownAbility=NonPokemonBatch2Test.DATA.pokemon("sv3-5_en_113").orElseThrow().ability("lucky-bonus").orElseThrow();c.attack=GeneratedRuleBatch8Test.hit(1000,false);var m=GeneratedRuleBatch28Test.fixture(c);UUID a=GeneratedRuleBatch8Test.A;var chansey=hand(m,a,"attacker");var hand=PairedTrainerPlayTest.zone(m,a,"hand");var prizes=PairedTrainerPlayTest.zone(m,a,"prizes");hand.remove(chansey);hand.add(prizes.set(0,chansey));m.playTrainer(a,hand(m,a,"trainer").instanceId(),null);check(!has(m,a,active(m,a)),"Prize fixture failed Basic suppression");m.attack(a,"hit");check(m.phase()==MatchPhase.PRIZE_SELECTION,"Prize fixture did not KO");m.takePrizeAt(a,0);check(m.hasPendingLuckyBonus(a),"Lab incorrectly suppressed Prize pre-movement Ability");m.decideLuckyBonus(a,accept);if(accept)check(m.benchPokemonView(a).stream().anyMatch(p->EventTargetBindingTest.field(m).topCard(a,p.pokemonId()).instanceId().equals(chansey.instanceId())),"Lucky Bonus did not put the actual prize on Bench");NonPokemonBatch103Test.settle(m);
    }}
    static void handPlayLock(){UUID a=DynamicPassiveModifierTest.A,b=DynamicPassiveModifierTest.B;
        var lock=DiscardAbilityCountTest.passive("lock","{\"type\":\"passive_pokemon_play_lock\",\"target\":\"OPPONENT_ACTIVE\",\"source_active_only\":true,\"has_abilities\":true,\"except_name_contains\":\"Team Rocket's\"}");
        var m=DynamicPassiveModifierTest.fixture(DynamicPassiveModifierTest.plainTool(),profile(),EnergyProfile.fixed(EnergyType.COLORLESS,2),GeneratedRuleBatch8Test.hit(40,false),List.of(lock));m.endTurn(a);m.evolveByEffect(b,active(m,b),hand(m,b,"evolved").instanceId(),EvolutionPermission.CARD_EFFECT_ALL_TIMING);m.endTurn(b);check(!m.canPlayBasicPokemonToBench(a,"basic"),"Play lock fixture did not block hand Ability");m.playTrainer(a,hand(m,a,"stadium").instanceId(),null);check(m.canPlayBasicPokemonToBench(a,"basic"),"Lab removed activation but left hand Ability possession");check(!m.canEvolve(a,active(m,a),"evolved"),"Lab erased an evolved hand Ability");m.playBasicPokemonToBench(a,hand(m,a,"basic").instanceId());m.discardStadiumByEffect(a);check(!m.canPlayBasicPokemonToBench(a,"basic"),"Hand play lock failed to restore after Lab");
    }
    static void ai(){for(var difficulty:AiDifficulty.values()){var m=aiGame(IDS.getFirst());UUID p=m.currentPlayer();m.playTrainer(p,hand(m,p,"trainer").instanceId(),null);var seats=NonPokemonBatch103Test.seats(m);var s=MatchSession.multiplayer(m,seats.get(0),seats.get(1));AiCardOperationTest.settle(s,difficulty);AiCardOperationTest.finish(s,difficulty);check(m.phase()==MatchPhase.FINISHED,"Lab AI stalled");}}
    static void schema(){var program=profile().ongoingProgram();for(var source:List.of(PassiveModifierProgram.Source.TOOL,PassiveModifierProgram.Source.ENERGY,PassiveModifierProgram.Source.ABILITY))GeneratedRuleBatch8Test.reject(()->PassiveModifierProgram.validate(program,source));var b=program.triggers().getFirst();GeneratedRuleBatch8Test.reject(()->PassiveModifierProgram.validate(new EffectProgram(List.of(new TriggeredEffects(EffectTrigger.PASSIVE,List.of(new ConditionDefinition(ConditionType.IS_ACTIVE,Map.of(),List.of())),b.effects()))),PassiveModifierProgram.Source.STADIUM));}
}
